475			t.Fatal("负上限必须报错")
476		}
477	
478		// 合法设置后再下单致申请后合计溢出：下单整体报错并留一条拒绝，上限保持不变。
479		e2, _ := NewEngine(math.MaxInt64)
480		mustSetMax(t, e2, "A", 10)
481		mustQuote(t, e2, "A", Quote{Seq: 1, Moment: 1, Price: 5}, 1)
482		bid := mustBuy(t, e2, "A", 1, 5)
483		if _, err := e2.Fill(Trade{TradeID: 1, OrderID: bid, Symbol: "A", Side: Buy, Price: 5, Qty: 1}); err != nil {
484			t.Fatal(err)
485		}
486		mustQuote(t, e2, "A", Quote{Seq: 2, Moment: 2, Price: math.MaxInt64}, 1) // 持仓 1×MaxInt64
487		if _, err := e2.SetPositionAmountLimit(math.MaxInt64); err != nil {
488			t.Fatalf("合计恰为 MaxInt64 时设置应成功: %v", err)
489		}
490		before = len(e2.Records())
491		// 限价 5 通过现金检查；占用按 max(限价 5, 报价 MaxInt64) 计，与持仓合计溢出。
492		if _, err := e2.Buy("A", 1, 5); !errors.Is(err, ErrInt64Overflow) {
493			t.Fatalf("申请后合计溢出必须返回 ErrInt64Overflow，实际 %v", err)
494		}
495		if len(e2.Records()) != before+1 || e2.Records()[before].Kind != RecordRejected {
496			t.Fatal("溢出下单只能增加一条拒绝记录")
497		}
498		if st := e2.PositionAmountStatus(); !st.Enabled || st.Limit != math.MaxInt64 {
499			t.Fatalf("溢出下单不得改写上限: %+v", st)
500		}
501	}
