503	func TestAmountOverflowQuoteBatchRollsBack(t *testing.T) {
504		e, _ := NewEngine(1_000_000)
505		mustSetMax(t, e, "A", 10)
506		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
507		id := mustBuy(t, e, "A", 5, 10) // 占用 50
508		if _, err := e.SetPositionAmountLimit(1_000_000); err != nil {
509			t.Fatal(err)
510		}
511	
512		// seq3 溢出报价先等待；补齐 seq2 时链中 seq3 使 5×MaxInt64 溢出，整批回滚。
513		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: math.MaxInt64}, 0)
514		before := len(e.Records())
515		n, err := e.UpdateQuote("A", Quote{Seq: 2, Moment: 2, Price: 11})
516		if !errors.Is(err, ErrInt64Overflow) || n != 0 {
517			t.Fatalf("链中金额溢出必须整体报错且 0 条生效: n=%d err=%v", n, err)
518		}
519		q, _ := e.CurrentQuote("A")
520		if q.Seq != 1 || q.Price != 10 {
521			t.Fatalf("回滚后最新报价应停留在 seq1@10: %+v", q)
522		}
523		if !e.HasGap("A") {
524			t.Fatal("回滚后 seq3 必须仍在等待")
525		}
526		if o, _ := e.Order(id); o.Status != StatusPending {
527			t.Fatalf("回滚不得撤单: %+v", o)
528		}
529		if e.ReservedCash() != 50 {
530			t.Fatalf("回滚不得改变占用: %d", e.ReservedCash())
531		}
532		if len(e.Records()) != before+1 || e.Records()[before].Kind != RecordRejected {
533			t.Fatal("整批报错只能增加一条拒绝记录")
534		}
535	}
536	
537	func TestAmountRecordsImmutable(t *testing.T) {
538		e := setupAmt(t)
539		if _, err := e.SetPositionAmountLimit(80); err != nil {
540			t.Fatal(err)
541		}
542		mustBuy(t, e, "A", 4, 10) // 占用 40
543		mustBuy(t, e, "B", 2, 20) // 占用 40，合计 80
544		// A 报价涨到 12：A 买单变 48、B 仍 40，合计 88 超限，撤销编号更大的 B 买单。
545		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 12}, 1)
546		rec := lastAmountRecord(t, e, RecordCanceled)
547		if len(rec.AmtQuoteRefs) != 2 || rec.AmtTotal != 88 {
548			t.Fatalf("前置撤单快照错误: %+v", rec)
549		}
550	
551		// 篡改查询副本不得影响内部记录。
552		recs := e.Records()
553		for i := range recs {
554			if recs[i].AmtQuoteRefs != nil {
555				recs[i].AmtQuoteRefs[0].Price = 999
556				recs[i].AmtTotal = 1
557			}
558		}
559		again := lastAmountRecord(t, e, RecordCanceled)
560		if again.AmtQuoteRefs[0].Price == 999 || again.AmtTotal == 1 {
561			t.Fatalf("内部记录不得被查询副本改写: %+v", again)
562		}
563	
564		// 后续报价、上限调整不得改写历史记录。
565		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: 1}, 1)
566		if _, err := e.SetPositionAmountLimit(999); err != nil {
567			t.Fatal(err)
568		}
569		again = lastAmountRecord(t, e, RecordCanceled)
570		if again.AmtLimit != 80 || again.AmtQuoteRefs[0].Price != 12 {
571			t.Fatalf("历史撤单快照不得被后续变化改写: %+v", again)
572		}
573	}
574	
575	func TestAmountReplayQuoteAndTradeHasNoNewEffect(t *testing.T) {
576		e := setupAmt(t)
577		if _, err := e.SetPositionAmountLimit(100); err != nil {
578			t.Fatal(err)
579		}
580		bid := mustBuy(t, e, "A", 10, 10)
581		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 20}, 1)
582		if o, _ := e.Order(bid); o.Status != StatusCanceled {
583			t.Fatal("前置应撤单")
584		}
585		recs := len(e.Records())
586	
587		// 相同报价重放：不新增业务效果或记录。
588		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 20}, 0)
589		if len(e.Records()) != recs {
