}

func mustBuy(t *testing.T, e *Engine, symbol string, qty, limit int64) int64 {
	t.Helper()
	id, err := e.Buy(symbol, qty, limit)
	if err != nil {
		t.Fatalf("Buy(%s,%d,%d) 意外错误: %v", symbol, qty, limit, err)
	}
	return id
}

